export default `:root{--cream:#FFF6E8;--paper:#FFFCF5;--wood-dark:#7A4A26;--wood-light:#E4B07C;--gold:#FFC94D;--gold-edge:#E0A02E;--amber:#FF9F45;--amber-edge:#E27E24;--teal:#2E9E93;--teal-dark:#1F7A71;--coral:#FF6F59;--coral-dark:#E8543F;--ink:#4A3325;--ink-soft:#8A7360;--success:#5FB86A;--shadow:0 6px 0 rgba(74,51,37,.18)}*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}html,body{min-height:100vh;margin:0;background:radial-gradient(circle at 15% 8%,#FFEBC9 0%,transparent 45%),radial-gradient(circle at 90% 85%,#FFE0C4 0%,transparent 50%),var(--cream);color:var(--ink);font-family:Nunito,sans-serif}button{-webkit-user-select:none;user-select:none}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
`;